   979  /* Adds an constant set named 'name' to 'const_sets', replacing any existing
   980   * constant set entry with the given name. */
   981  void
   982  expr_const_sets_add(struct shash *const_sets, const char *name,
   983                      const char *const *values, size_t n_values,
   984                      bool convert_to_integer)
   985  {
   986      /* Replace any existing entry for this name. */
   987      expr_const_sets_remove(const_sets, name);
   988
   989      struct expr_constant_set *cs = xzalloc(sizeof *cs);
   990      cs->in_curlies = true;
   991      cs->n_values = 0;
   992      cs->values = xmalloc(n_values * sizeof *cs->values);
   993      if (convert_to_integer) {
   994          cs->type = EXPR_C_INTEGER;
   995          for (size_t i = 0; i < n_values; i++) {
   996              /* Use the lexer to convert each constant set into the proper
   997               * integer format. */
   998              struct lexer lex;
   999              lexer_init(&lex, values[i]);
  1000              lexer_get(&lex);
  1001              if (lex.token.type != LEX_T_INTEGER
  1002                  && lex.token.type != LEX_T_MASKED_INTEGER) {
  1003                  VLOG_WARN("Invalid constant set entry: '%s', token type: %d",
  1004                            values[i], lex.token.type);
  1005              } else {
  1006                  union expr_constant *c = &cs->values[cs->n_values++];
  1007                  c->value = lex.token.value;
  1008                  c->format = lex.token.format;
  1009                  c->masked = lex.token.type == LEX_T_MASKED_INTEGER;
  1010                  if (c->masked) {
  1011                      c->mask = lex.token.mask;
  1012                  }
  1013              }
  1014              lexer_destroy(&lex);
  1015          }
  1016      } else {
  1017          cs->type = EXPR_C_STRING;
  1018          for (size_t i = 0; i < n_values; i++) {
  1019              union expr_constant *c = &cs->values[cs->n_values++];
  1020              c->string = xstrdup(values[i]);
  1021          }
  1022      }
  1023
  1024      shash_add(const_sets, name, cs);
  1025  }
