   324  static void
   325  lex_parse_hex_integer(const char *start, size_t len, struct lex_token *token)
   326  {
   327      const char *in = start + (len - 1);
   328      uint8_t *out = token->value.u8 + (sizeof token->value.u8 - 1);
   329
   330      for (int i = 0; i < len; i++) {
   331          int hexit = hexit_value(in[-i]);
   332          if (hexit < 0) {
   333              lex_error(token, "Invalid syntax in hexadecimal constant.");
   334              return;
   335          }
   336          if (hexit && i / 2 >= sizeof token->value.u8) {
   337              lex_error(token, "Hexadecimal constant requires more than "
   338                        "%"PRIuSIZE" bits.", 8 * sizeof token->value.u8);
   339              return;
   340          }
   341          out[-(i / 2)] |= i % 2 ? hexit << 4 : hexit;
   342      }
   343      token->format = LEX_F_HEXADECIMAL;
   344  }
   345
   346  static const char *
   347  lex_parse_integer__(const char *p, struct lex_token *token)
   348  {
   349      lex_token_init(token);
   350      token->type = LEX_T_INTEGER;
   351      memset(&token->value, 0, sizeof token->value);
   352
   353      /* Find the extent of an "integer" token, which can be in decimal or
   354       * hexadecimal, or an Ethernet address or IPv4 or IPv6 address, as 'start'
   355       * through 'end'.
   356       *
   357       * Special cases we handle here are:
   358       *
   359       *     - The ellipsis token "..", used as e.g. 123..456.  A doubled dot
   360       *       is never valid syntax as part of an "integer", so we stop if
   361       *       we encounter two dots in a row.
   362       *
   363       *     - Syntax like 1.2.3.4:1234 to indicate an IPv4 address followed by a
   364       *       port number should be considered three tokens: 1.2.3.4 : 1234.
   365       *       The obvious approach is to allow just dots or just colons within a
   366       *       given integer, but that would disallow IPv4-mapped IPv6 addresses,
   367       *       e.g. ::ffff:192.0.2.128.  However, even in those addresses, a
   368       *       colon never follows a dot, so we stop if we encounter a colon
   369       *       after a dot.
   370       *
   371       *       (There is no corresponding way to parse an IPv6 address followed
   372       *       by a port number: ::1:2:3:4:1234 is unavoidably ambiguous.)
   373       */
   374      const char *start = p;
   375      const char *end = start;
   376      bool saw_dot = false;
   377      while (isalnum((unsigned char) *end)
   378             || (*end == ':' && !saw_dot)
   379             || (*end == '.' && end[1] != '.')) {
   380          if (*end == '.') {
   381              saw_dot = true;
   382          }
   383          end++;
   384      }
   385      size_t len = end - start;
   386
   387      int n;
   388      struct eth_addr mac;
   389
   390      if (!len) {
   391          lex_error(token, "Integer constant expected.");
   392      } else if (len == 17
   393                 && ovs_scan(start, ETH_ADDR_SCAN_FMT"%n",
   394                             ETH_ADDR_SCAN_ARGS(mac), &n)
   395                 && n == len) {
   396          token->value.mac = mac;
   397          token->format = LEX_F_ETHERNET;
   398      } else if (start + strspn(start, "0123456789") == end) {
   399          if (p[0] == '0' && len > 1) {
   400              lex_error(token, "Decimal constants must not have leading zeros.");
   401          } else {
   402              unsigned long long int integer;
   403              char *tail;
   404
   405              errno = 0;
   406              integer = strtoull(p, &tail, 10);
   407              if (tail != end || errno == ERANGE) {
   408                  lex_error(token, "Decimal constants must be less than 2**64.");
   409              } else {
   410                  token->value.integer = htonll(integer);
   411                  token->format = LEX_F_DECIMAL;
   412              }
   413          }
   414      } else if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) {
   415          if (len > 2) {
   416              lex_parse_hex_integer(start + 2, len - 2, token);
   417          } else {
   418              lex_error(token, "Hex digits expected following 0%c.", p[1]);
   419          }
   420      } else if (len < INET6_ADDRSTRLEN) {
   421          char copy[INET6_ADDRSTRLEN];
   422          memcpy(copy, p, len);
   423          copy[len] = '\0';
   424
   425          if (ip_parse(copy, &token->value.ipv4)) {
   426              token->format = LEX_F_IPV4;
   427          } else if (ipv6_parse(copy, &token->value.ipv6)) {
   428              token->format = LEX_F_IPV6;
   429          } else {
   430              lex_error(token, "Invalid numeric constant.");
   431          }
   432      } else {
   433          lex_error(token, "Invalid numeric constant.");
   434      }
   435
   436      ovs_assert(token->type == LEX_T_INTEGER || token->type == LEX_T_ERROR);
   437      return end;
   438  }
