   440  static const char *
   441  lex_parse_mask(const char *p, struct lex_token *token)
   442  {
   443      struct lex_token mask;
   444
   445      /* Parse just past the '/' as a second integer.  Handle errors. */
   446      p = lex_parse_integer__(p + 1, &mask);
   447      if (mask.type == LEX_T_ERROR) {
   448          lex_token_swap(&mask, token);
   449          lex_token_destroy(&mask);
   450          return p;
   451      }
   452      ovs_assert(mask.type == LEX_T_INTEGER);
   453
   454      /* Now convert the value and mask into a masked integer token.
   455       * We have a few special cases. */
   456      token->type = LEX_T_MASKED_INTEGER;
   457      memset(&token->mask, 0, sizeof token->mask);
   458      uint32_t prefix_bits = ntohll(mask.value.integer);
   459      if (token->format == mask.format) {
   460          /* Same format value and mask is always OK. */
   461          token->mask = mask.value;
   462      } else if (token->format == LEX_F_IPV4
   463                 && mask.format == LEX_F_DECIMAL
   464                 && prefix_bits <= 32) {
   465          /* IPv4 address with decimal mask is a CIDR prefix. */
   466          token->mask.integer = htonll(ntohl(be32_prefix_mask(prefix_bits)));
   467      } else if (token->format == LEX_F_IPV6
   468                 && mask.format == LEX_F_DECIMAL
   469                 && prefix_bits <= 128) {
   470          /* IPv6 address with decimal mask is a CIDR prefix. */
   471          token->mask.ipv6 = ipv6_create_mask(prefix_bits);
   472      } else if (token->format == LEX_F_DECIMAL
   473                 && mask.format == LEX_F_HEXADECIMAL
   474                 && token->value.integer == 0) {
   475          /* Special case for e.g. 0/0x1234. */
   476          token->format = LEX_F_HEXADECIMAL;
   477          token->mask = mask.value;
   478      } else {
   479          lex_error(token, "Value and mask have incompatible formats.");
   480          return p;
   481      }
   482
   483      /* Check invariant that a 1-bit in the value corresponds to a 1-bit in the
   484       * mask. */
   485      for (int i = 0; i < ARRAY_SIZE(token->mask.be32); i++) {
   486          ovs_be32 v = token->value.be32[i];
   487          ovs_be32 m = token->mask.be32[i];
   488
   489          if (v & ~m) {
   490              lex_error(token, "Value contains unmasked 1-bits.");
   491              break;
   492          }
   493      }
   494
   495      /* Done! */
   496      lex_token_destroy(&mask);
   497      return p;
   498  }
