   500  static const char *
   501  lex_parse_integer(const char *p, struct lex_token *token)
   502  {
   503      p = lex_parse_integer__(p, token);
   504      if (token->type == LEX_T_INTEGER && *p == '/') {
   505          p = lex_parse_mask(p, token);
   506      }
   507      return p;
   508  }
