   510  static const char *
   511  lex_parse_string(const char *p, struct lex_token *token)
   512  {
   513      const char *start = ++p;
   514      char * s = NULL;
   515      for (;;) {
   516          switch (*p) {
   517          case '\0':
   518              lex_error(token, "Input ends inside quoted string.");
   519              return p;
   520
   521          case '"':
   522              token->type = (json_string_unescape(start, p - start, &s)
   523                             ? LEX_T_STRING : LEX_T_ERROR);
   524              lex_token_strset(token, s);
   525              return p + 1;
   526
   527          case '\\':
   528              p++;
   529              if (*p) {
   530                  p++;
   531              }
   532              break;
   533
   534          default:
   535              p++;
   536              break;
   537          }
   538      }
   539  }
