   541  static bool
   542  lex_is_id1(unsigned char c)
   543  {
   544      return ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
   545              || c == '_' || c == '.');
   546  }
   547
   548  static bool
   549  lex_is_idn(unsigned char c)
   550  {
   551      return lex_is_id1(c) || (c >= '0' && c <= '9');
   552  }
   553
   554  static const char *
   555  lex_parse_id(const char *p, enum lex_type type, struct lex_token *token)
   556  {
   557      const char *start = p;
   558
   559      do {
   560          p++;
   561      } while (lex_is_idn(*p));
   562
   563      token->type = type;
   564      lex_token_strcpy(token, start, p - start);
   565      return p;
   566  }
   567
   568  static const char *
   569  lex_parse_addr_set(const char *p, struct lex_token *token)
   570  {
   571      p++;
   572      if (!lex_is_id1(*p)) {
   573          lex_error(token, "`$' must be followed by a valid identifier.");
   574          return p;
   575      }
   576
   577      return lex_parse_id(p, LEX_T_MACRO, token);
   578  }
